rint(f\"TRACE_EVENT_COUNTS {dict(sorted(event_counts.items()))}\")\n    print(f\"TRACE_PAYLOAD_COUNTS {dict(sorted(payload_counts.items()))}\")\n    print(\"PROVENANCE_CHECK_COMPLETE\")\n\n\nif __name__ == \"__main__\":\n    main()\n"},"/audit-output/evidence/run_logged.sh":{"type":"add","content":"#!/usr/bin/env bash\nset -u\n\nif [[ \"$#\" -lt 2 ]]; then\n  echo \"usage: run_logged.sh LABEL COMMAND [ARG ...]\" >&2\n  exit 64\nfi\n\nlabel=\"$1\"\nshift\nlog=\"/audit-output/evidence/logs/${label}.log\"\n\n{\n  printf 'WORKDIR: %s\\n' \"$PWD\"\n  printf 'COMMAND:'\n  printf ' %q' \"$@\"\n  printf '\\n'\n  printf 'START_UTC: '\n  date -u '+%Y-%m-%dT%H:%M:%SZ'\n  \"$@\"\n  status=$?\n  printf 'EXIT_STATUS: %d\\n' \"$status\"\n  printf 'END_UTC: '\n  date -u '+%Y-%m-%dT%H:%M:%SZ'\n  exit \"$status\"\n} >\"$log\" 2>&1\n"}},"status":"completed"}}
